import{Module}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{THREE,materials}from'./geometry.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';
function build(host,kind){const frame=new THREE.Group();frame.name='M5Camera-X own static '+kind+' actual mating frame';frame.rotation.x=Math.PI/2;frame.position.y=-6.6;host.body.add(frame);const saved=host.body;host.body=frame;let parts;try{parts=addCadParts(host,data.filter(p=>p.role===kind),{white:materials.plastic(0xe7e6dc,{roughness:.74})});}finally{host.body=saved;}host.m5CameraXAccessory={kind,frame,parts,nativeMesh:Object.values(parts)[0]};}
export class LegoClip extends Module{static meta={id:'m5stack.unit.m5camera-x.lego',name:'M5Camera-X own LEGO retaining clip',sku:'U038 accessory',connector:spec.mount.connector};build(){build(this,'lego');}}
export class Wall1515 extends Module{static meta={id:'m5stack.unit.m5camera-x.wall1515',name:'M5Camera-X own Wall-1515 adapter',sku:'U038 accessory',connector:spec.mount.connector};build(){build(this,'wall1515');}}
